export const getCustomerServiceTicketsCreateUrl = (params: CustomerServiceTicketsCreateParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `https://api.sumit.co.il/customerservice/tickets/create/?${stringifiedParams}` : `https://api.sumit.co.il/customerservice/tickets/create/`
}

export const customerServiceTicketsCreate = async (params: CustomerServiceTicketsCreateParams,
    customerServiceTicketsCreateBody?: CustomerServiceTicketsCreateBody, options?: Parameters<typeof sumitFetch>[1]): Promise<ResponseCustomerServiceTicketsCreateResponse> => {
    const formData = new FormData();
if(customerServiceTicketsCreateBody?.Attachments !== undefined) {
 customerServiceTicketsCreateBody?.Attachments.forEach(value => formData.append(`Attachments`, value));
 }

  return sumitFetch<ResponseCustomerServiceTicketsCreateResponse>(getCustomerServiceTicketsCreateUrl(params),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}



